1	/*
2	 * Rounding — a single rule with two faces.
3	 *
4	 * Money is only ever settled in whole gold pieces, and a fraction of a gold
5	 * piece always falls to MHPCO. Which way that rounds depends on who is paying:
6	 * a premium the customer owes rounds up, a payout MHPCO owes rounds down.
7	 * Both functions below are that one rule; keep them together so a change of
8	 * heart about it is a change in one place.
9	 */
10	
11	/** Premiums are rounded up — the fraction falls to MHPCO. */
12	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
13	
14	/** Payouts are rounded down — the fraction stays with MHPCO. */
15	const roundPayoutDown = (amount: number): number => Math.floor(amount);
16	
17	/** How many of each kind, where `kindOf` says what kind a value is. */
18	const countByKind = <T>(
19	  values: T[],
20	  kindOf: (value: T) => string,
21	): Map<string, number> => {
22	  const counts = new Map<string, number>();
23	  for (const value of values) {
24	    const kind = kindOf(value);
25	    counts.set(kind, (counts.get(kind) ?? 0) + 1);
26	  }
27	  return counts;
28	};
29	
30	export type Customer = { yearsWithMHPCO: number };
31	
32	export type Scenario = {
33	  customer: Customer;
34	  steps: Step[];
35	};
36	
37	export type QuoteStep = { op: string; items: Item[] };
38	
39	export type Damage = { itemType: string; amount: number };
40	
41	export type Incident = { cause: string; damages: Damage[] };
42	
43	export type ClaimStep = { op: string; policy: number; incident: Incident };
44	
45	export type Step = QuoteStep | ClaimStep;
46	
47	export type Item = { type: string } & Record<string, unknown>;
48	
49	export type QuoteResult = { premium: number };
50	
51	export type ClaimResult = { payout: number; remainingCap: number };
52	
53	export type Result = QuoteResult | ClaimResult;
54	
55	export type ScenarioOutcome = { results: Result[] };
56	
57	// ---------------------------------------------------------------------------
58	// Quoting — what a policy costs the customer.
59	// ---------------------------------------------------------------------------
60	
61	/** Base premium of each insurable item type. */
62	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	/** A block is exactly this many items of one and the same type. */
72	const BLOCK_SIZE = 3;
73	
74	/** Special base premium charged for a complete block, instead of the per-item sum. */
75	const BLOCK_BASE_PREMIUM = 60;
76	
77	/** Number of items of each type on a policy. */
78	const countItemsByType = (items: Item[]): Map<string, number> =>
79	  countByKind(items, (item) => item.type);
80	
81	/**
82	 * Base premium of a single item of the given type, before block pricing or
83	 * surcharge. A type MHPCO does not insure has no base premium, so this throws
84	 * rather than inventing one — an unpriceable item must not silently become a
85	 * NaN premium.
86	 *
87	 * This is also the only place a quote checks that a type is insurable at all.
88	 * Every item reaches it via the surcharge pass, which prices items one by one;
89	 * the block path in `groupBasePremium` skips the lookup, so it alone would let
90	 * a complete block of an unknown type through.
91	 */
92	const basePremiumOfType = (type: string): number => {
93	  const basePremium = BASE_PREMIUM_BY_TYPE[type];
94	  if (basePremium === undefined) {
95	    throw new Error(`Unknown item type: ${type}`);
96	  }
97	  return basePremium;
98	};
99	
100	/** Base premium for all items of one and the same type. */
101	const groupBasePremium = (type: string, count: number): number =>
102	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
103	
104	/** Base premium of a policy covering the given items. */
105	const calculateBasePremium = (items: Item[]): number =>
106	  [...countItemsByType(items)].reduce(
107	    (total, [type, count]) => total + groupBasePremium(type, count),
108	    0,
109	  );
110	
111	/** Risk surcharge charged on the base premium of a cursed item. */
112	const CURSE_RATE = 0.5;
113	
114	/** Enchantment level from which an item counts as highly enchanted. */
115	const HIGH_ENCHANTMENT_LEVEL = 5;
116	
117	/** Risk surcharge charged on the base premium of a highly enchanted item. */
118	const HIGH_ENCHANTMENT_RATE = 0.3;
119	
120	/** True when the item is enchanted strongly enough to attract the surcharge. */
121	const isHighlyEnchanted = (item: Item): boolean =>
122	  typeof item.enchantment === "number" &&
123	  item.enchantment >= HIGH_ENCHANTMENT_LEVEL;
124	
125	/** Combined rate of the surcharges an item attracts. */
126	const itemSurchargeRate = (item: Item): number => {
127	  const curseRate = item.cursed ? CURSE_RATE : 0;
128	  const enchantmentRate = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RATE : 0;
129	  return curseRate + enchantmentRate;
130	};
131	
132	/** Surcharges an individual item attracts, charged on its own base premium. */
133	const itemSurcharges = (item: Item): number =>
134	  basePremiumOfType(item.type) * itemSurchargeRate(item);
135	
136	/** Surcharges that attach to individual items rather than to the whole policy. */
137	const calculateItemSurcharges = (items: Item[]): number =>
138	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
139	
140	/** Initial assessment surcharge on a customer's first insurance. */
141	const FIRST_INSURANCE_RATE = 0.1;
142	
143	/** Years of business from which a customer counts as long-standing. */
144	const LOYALTY_YEARS = 2;
145	
146	/** Discount a long-standing customer receives on the policy base premium. */
147	const LOYALTY_RATE = -0.2;
148	
149	/** True when the customer has been with MHPCO long enough to earn the discount. */
150	const isLongStanding = (customer: Customer): boolean =>
151	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
152	
153	/** Discount on every contract after the customer's first. */
154	const FOLLOW_UP_RATE = -0.15;
155	
156	/** True when this is not the customer's first contract. */
157	const isFollowUpContract = (
158	  _customer: Customer,
159	  previousContracts: number,
160	): boolean => previousContracts > 0;
161	
162	/**
163	 * Rates that attach to the policy as a whole. Each applies to the policy base
164	 * premium; positive rates are surcharges, negative ones discounts.
165	 */
166	const POLICY_RATES: {
167	  rate: number;
168	  applies: (customer: Customer, previousContracts: number) => boolean;
169	}[] = [
170	  { rate: FIRST_INSURANCE_RATE, applies: () => true },
171	  { rate: LOYALTY_RATE, applies: isLongStanding },
172	  { rate: FOLLOW_UP_RATE, applies: isFollowUpContract },
173	];
174	
175	/** Net of every policy-wide rate the customer qualifies for. */
176	const policyRate = (customer: Customer, previousContracts: number): number =>
177	  POLICY_RATES.reduce(
178	    (total, { rate, applies }) =>
179	      applies(customer, previousContracts) ? total + rate : total,
180	    0,
181	  );
182	
183	/** Net policy-wide adjustment, charged on the policy base premium. */
184	const calculatePolicyAdjustment = (
185	  policyBasePremium: number,
186	  customer: Customer,
187	  previousContracts: number,
188	): number => policyBasePremium * policyRate(customer, previousContracts);
189	
190	/** Flat fee added to every premium, regardless of the items insured. */
191	const PROCESSING_FEE = 5;
192	
193	/** Price a policy covering the given items. */
194	const quotePremium = (
195	  items: Item[],
196	  customer: Customer,
197	  previousContracts: number,
198	): number => {
199	  const policyBasePremium = calculateBasePremium(items);
200	  const surcharges = calculateItemSurcharges(items);
201	  const policyAdjustment = calculatePolicyAdjustment(
202	    policyBasePremium,
203	    customer,
204	    previousContracts,
205	  );
206	  return roundPremiumUp(
207	    policyBasePremium + surcharges + policyAdjustment + PROCESSING_FEE,
208	  );
209	};
210	
211	// ---------------------------------------------------------------------------
212	// Claims — what a policy pays out when insured items are damaged.
213	// ---------------------------------------------------------------------------
214	
215	/** Sum insured for each item type, per the MHPCO price list. */
216	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
217	  sword: 1000,
218	  amulet: 600,
219	  staff: 800,
220	  potion: 400,
221	  rune: 250,
222	  moonstone: 250,
223	};
224	
225	/** Excess the claimant bears on every damaged item. */
226	const DEDUCTIBLE = 100;
227	
228	/** A policy pays out at most this multiple of its insurance sum. */
229	const CAP_MULTIPLIER = 2;
230	
231	/** Total sum insured under a policy covering the given items. */
232	const insuranceSum = (items: Item[]): number =>
233	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
234	
235	/** Enchantment level from which damage is only partly reimbursed. */
236	const REDUCED_REIMBURSEMENT_LEVEL = 8;
237	
238	/** Share of the damage MHPCO reimburses on a heavily enchanted item. */
239	const REDUCED_REIMBURSEMENT_RATE = 0.5;
240	
241	/** Share of the damage MHPCO reimburses for the given insured item. */
242	const reimbursementRate = (item: Item): number =>
243	  typeof item.enchantment === "number" &&
244	  item.enchantment >= REDUCED_REIMBURSEMENT_LEVEL
245	    ? REDUCED_REIMBURSEMENT_RATE
246	    : 1;
247	
248	/** What MHPCO owes for a single damaged item, before the cap is considered. */
249	const damagePayout = (damage: Damage, item: Item): number =>
250	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
251	
252	/** A quoted policy, tracked so later claim steps can draw against its cap. */
253	type Policy = { items: Item[]; remainingCap: number };
254	
255	/** The policy a quote step establishes, with its cap untouched. */
256	const openPolicy = (items: Item[]): Policy => ({
257	  items,
258	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
259	});
260	
261	/**
262	 * The insured item a damage entry refers to.
263	 *
264	 * Throws when the policy covers no item of that type. Note this is a different
265	 * kind of failure from `basePremiumOfType`'s: that one rejects a type MHPCO
266	 * insures for nobody, this one rejects a type merely absent from *this*
267	 * contract.
268	 *
269	 * A previous refactor guessed these two messages only looked alike by accident;
270	 * the third rejection settled it. `rejectMoreDamagesThanInsuredItems` reports a
271	 * count mismatch, which has no offending value to name, so it cannot wear the
272	 * `"<reason>: <value>"` shape at all. Three throws, three sentences, no shared
273	 * shape to factor out — they stay separate inline throws until some caller
274	 * actually needs to tell error kinds apart programmatically.
275	 */
276	const damagedItem = (policy: Policy, damage: Damage): Item => {
277	  const item = policy.items.find((item) => item.type === damage.itemType);
278	  if (item === undefined) {
279	    throw new Error(
280	      `Damaged item not covered by the policy: ${damage.itemType}`,
281	    );
282	  }
283	  return item;
284	};
285	
286	/**
287	 * What MHPCO owes for one damage entry under the given policy: the entry is
288	 * matched to the insured item it refers to, and that item's clauses decide how
289	 * much of the damage is reimbursed.
290	 */
291	const policyDamagePayout = (policy: Policy, damage: Damage): number =>
292	  damagePayout(damage, damagedItem(policy, damage));
293	
294	/** Number of damage entries naming each item type. */
295	const countDamagesByType = (damages: Damage[]): Map<string, number> =>
296	  countByKind(damages, (damage) => damage.itemType);
297	
298	/**
299	 * Rejects an incident that reports more damaged items of a type than the policy
300	 * insures. Each insured item may be damaged once per incident, so a second
301	 * sword entry on a one-sword policy is a claim for an item that does not exist.
302	 */
303	const rejectMoreDamagesThanInsuredItems = (
304	  incident: Incident,
305	  policy: Policy,
306	): void => {
307	  const insuredCounts = countItemsByType(policy.items);
308	  for (const [itemType, damaged] of countDamagesByType(incident.damages)) {
309	    if (damaged > (insuredCounts.get(itemType) ?? 0)) {
310	      throw new Error(
311	        `More ${itemType} damages than insured items of that type`,
312	      );
313	    }
314	  }
315	};
316	
317	/** Rejects an incident reporting damage of a negative amount. */
318	const rejectNegativeDamageAmounts = (incident: Incident): void => {
319	  for (const damage of incident.damages) {
320	    if (damage.amount < 0) {
321	      throw new Error(`Damage amount must not be negative: ${damage.amount}`);
322	    }
323	  }
324	};
325	
326	/** What MHPCO owes for an entire incident, before the cap is considered. */
327	const grossIncidentPayout = (incident: Incident, policy: Policy): number =>
328	  incident.damages.reduce(
329	    (total, damage) => total + policyDamagePayout(policy, damage),
330	    0,
331	  );
332	
333	/**
334	 * Draws an amount owed against the policy's cap. A policy never pays out more
335	 * than the cap it has left, so the amount drawn is whichever is smaller.
336	 */
337	const drawAgainstCap = (policy: Policy, amountOwed: number): number => {
338	  const drawn = Math.min(roundPayoutDown(amountOwed), policy.remainingCap);
339	  policy.remainingCap -= drawn;
340	  return drawn;
341	};
342	
343	// ---------------------------------------------------------------------------
344	// Running a scenario — quote steps open policies, claim steps draw on them.
345	// ---------------------------------------------------------------------------
346	
347	/** True when the step reports damage against a policy rather than asking for a price. */
348	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
349	
350	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
351	  const policies = new Map<number, Policy>();
352	  let previousContracts = 0;
353	
354	  const handleQuote = (step: QuoteStep, stepIndex: number): QuoteResult => {
355	    const premium = quotePremium(
356	      step.items,
357	      scenario.customer,
358	      previousContracts,
359	    );
360	    previousContracts += 1;
361	    policies.set(stepIndex, openPolicy(step.items));
362	    return { premium };
363	  };
364	
365	  const handleClaim = (step: ClaimStep): ClaimResult => {
366	    const policy = policies.get(step.policy)!;
367	    rejectMoreDamagesThanInsuredItems(step.incident, policy);
368	    rejectNegativeDamageAmounts(step.incident);
369	    const payout = drawAgainstCap(
370	      policy,
371	      grossIncidentPayout(step.incident, policy),
372	    );
373	    return { payout, remainingCap: policy.remainingCap };
374	  };
375	
376	  const results = scenario.steps.map((step, stepIndex): Result =>
377	    isClaimStep(step) ? handleClaim(step) : handleQuote(step, stepIndex),
378	  );
379	
380	  return { results };
381	};
